def chunk(text, size=300):
    title, _, *turns = text.split("\n")
    groups = []
    for t in turns:  # {{new chunk at a question}}
        if not groups or "?" in t:
            groups.append([])
        groups[-1].append(t)
    out = []
    for q, *rest in groups:
        end = (rest or [q])[-1][1:6]
        top = [f"{title} [{q[1:6]}-{end}]", q]
        if len("\n".join(top + rest)) <= size:
            out.append("\n".join(top + rest))
            continue
        for t in rest:  # {{question on each piece}}
            who, said = t.split(": ", 1)
            n = size - len("".join(top) + who) - 4
            for p in split(said, n):
                out.append("\n".join(
                    top + [who + ": " + p]))
    return out
